  ui_story_30210601_36_dialog_content = "...",
  ui_story_30210601_37_dialog_content = "(It all sounds so poetic...)",
  ui_story_30210601_38_dialog_content = "(But it feels like it's impossible for me to immerse myself in nature the way Jola does!)",
  ui_story_30210601_39_dialog_content = "What do you think, PlayerName?",
  ui_story_30210601_40_dialog_content = "Do you feel the charm hidden in this grandest of art?",
