  ui_story_30210601_42_dialog_content = "To be precise, the theme of this art is \"The Beauty of Ephemeral Moments.\"",
  ui_story_30210601_43_dialog_content = "Although these petals floating on the waves and the azure sea form a stunning view...",
  ui_story_30210601_44_dialog_content = "Did you notice, PlayerName? Each wave carries some of the petals away with the tide.",
  ui_story_30210601_45_dialog_content = "Even if they're lucky not to be submerged, wilting won't take long to seize upon them, being on the sea without soil and nutrients.",
  ui_story_30210601_46_dialog_content = "But it is this blooming before death and despair... ah...",
