  ui_story_30210601_54_option_content = "It's quite despairing.",
  ui_story_30210601_55_dialog_content = "Despairing? Uh-hmm...",
  ui_story_30210601_56_dialog_content = "It seems you somewhat understand the inherent cruelty, PlayerName.",
  ui_story_30210601_57_dialog_content = "But I hope you can also take note of the beauty within this despair.",
