  ui_story_30210601_64_dialog_content = "Even in my childhood, I often experienced comforting beauty and happiness.",
  ui_story_30210601_65_dialog_content = "Like the days I spent gardening with my sister in the quiet courtyard of the orphanage.",
  ui_story_30210601_66_dialog_content = "The warm afternoon sun, the flowers blooming within the fence, and that most beautiful smile...",
  ui_story_30210601_67_dialog_content = "Your sister...",
  ui_story_30210601_68_dialog_content = "The days of old have faded, but the beauty I perceived then remains in my mind.",
