  ui_story_30210601_71_dialog_content = "Ah, you are quite perceptive, PlayerName. I'm pleased.",
  ui_story_30210601_72_dialog_content = "The beauty you speak of is indeed an indelible memory for me.",
  ui_story_30210601_73_dialog_content = "But after my sister left, time and all my sensations seemed to freeze...",
  ui_story_30210601_74_dialog_content = "Looking at the flower field inside the fence, I fell into deep contemplation.",
  ui_story_30210601_75_dialog_content = "Those beautiful flowers that my sister and I planted together...",
  ui_story_30210601_76_dialog_content = "Why could they still bloom in the courtyard after she had gone?",
  ui_story_30210601_77_dialog_content = "Perhaps it's because... they were cared for too well before that time?",
  ui_story_30210601_78_dialog_content = "So I watched them day and night, as they withered and fell in the courtyard...",
  ui_story_30210601_79_dialog_content = "It was truly grotesque.",
  ui_story_30210601_80_dialog_content = "But one day, as I was picking up the petals alone, I had an epiphany! The beauty of the flowers in the past—",
  ui_story_30210601_81_dialog_content = "That tranquility and happiness bloomed from my sister's company.",
  ui_story_30210601_82_dialog_content = "But... when she left, that beauty naturally withered.",
  ui_story_30210601_83_dialog_content = "Yet the sting, sorrow, and helplessness that come with wilting... isn't that also a way for them to convey beauty?",
  ui_story_30210601_84_dialog_content = "It seems your sister's departure was quite a blow to you...",
  ui_story_30210601_85_dialog_content = "A blow? No, no... this event enlightened me on the topic of art's permanence.",
  ui_story_30210601_86_dialog_content = "Flowers struggle at the brink of wilting to unleash an eternal vitality, their fragrance overwhelming...",
  ui_story_30210601_87_dialog_content = "This is the charm of love and death... the charm of the foolish desire for immortality...",
  ui_story_30210601_88_dialog_content = "Speaking of which, PlayerName, do you believe in the possibility of undying love in this world?",
  ui_story_30210601_89_dialog_content = "Undying?",
