  ui_story_30210601_91_dialog_content = "Yes, beauty... beauty can be elevated.",
  ui_story_30210601_92_dialog_content = "And this elevation is a direct result of your arrival.",
  ui_story_30210601_93_dialog_content = "While witnessing this constant wilting and loss in this endless cycle, meeting the new you has been a truly precious occurrence.",
  ui_story_30210601_94_dialog_content = "So, may I ask you to accept this gift?",
  ui_story_30210601_95_dialog_content = "Huh? A gift?",
