  ui_story_30210601_99_dialog_content = "Its thorns have been removed.",
  ui_story_30210601_100_dialog_content = "This represents the fact that this love will not hurt you in the slightest.",
  ui_story_30210601_101_dialog_content = "Its roots have also been removed.",
  ui_story_30210601_102_dialog_content = "This represents the fact that this love will never flee. It will forever accompany you in its current, perfect form.",
  ui_story_30210601_103_dialog_content = "But... if that's the case, doesn't it feel like Caelum is...",
