  ui_story_30210601_108_dialog_content = "Well, I don't quite understand things on an eternal scale, but for now, speaking as someone who lives in the present...",
  ui_story_30210601_109_dialog_content = "If we don't handle that complaint, there's gonna be trouble on the Colossus!",
  ui_story_30210601_110_dialog_content = "So, about the fence... Ah, did you intentionally set it up to make me come find you?",
  ui_story_30210601_111_dialog_content = "Haha, please don't worry about that. I have no intention of expanding the fence. Of course, I'll take care of it accordingly.",
  ui_story_30210601_112_dialog_content = "If you can just hold on to this love tightly, whether you are outside or inside the fence, what difference does it make?",
  ui_story_30210601_113_dialog_content = "This topic of love... I still don't quite understand it. But this flower... I'll cherish it, truly.",
  ui_story_30210601_114_dialog_content = "... Thank you.",
  ui_story_30210601_115_dialog_content = "But before returning to the Colossus, could you please lie here with me for a while longer? Just a little while.",
